"""Closing orchestration shared by the CLI and the HTTP API: read, close, optional inference layer or revision, publish."""
from pathlib import Path
import os

from .audit import AuditLog
from .closing import close_month
from .inference import run_inference, run_revision, validate_decisions
from .llm_cache import ResponseCache
from .readers import read_inputs
from .reporting import now, publish_result
from .resolver import AnthropicResolver, CachedResolver, TokenBudget

NO_KEY_WARNING = 'ANTHROPIC_API_KEY not set: inference layer off, same as --no-llm'


def run_closing(input_path, closing_policy, inference_policy, period, output, resolver=None, cache=None, budget=None, use_llm=True):
    """Closes the period and publishes it. The layer runs only with use_llm and a resolver or ANTHROPIC_API_KEY; otherwise the output equals --no-llm."""
    warning, started_at = None, now()
    if use_llm and resolver is None and not os.environ.get('ANTHROPIC_API_KEY'):
        use_llm, warning = False, NO_KEY_WARNING
    bundle = read_inputs(input_path)
    result = close_month(bundle,closing_policy,period)
    audit, events = None, []
    if use_llm:
        audit = AuditLog()
        inner = resolver or AnthropicResolver(prompt_version=inference_policy['prompt_version'])
        budget = budget or TokenBudget(int(os.environ.get('LLM_BUDGET_TOKENS',200000)))
        events = run_inference(bundle,result,closing_policy,inference_policy,CachedResolver(inner,cache or ResponseCache('.cache/llm')),audit,budget)
    manifest = publish_result(bundle,result,closing_policy,period,output,started_at=started_at,layer={'ligada':use_llm,'auditoria':use_llm})
    if audit:
        audit.write(Path(output)/'auditoria.jsonl')
    return {'result':result, 'manifest':manifest, 'events':events, 'audit':audit, 'aviso':warning}


def run_revision_closing(input_path, closing_policy, inference_policy, period, output, parent_dir, decisions):
    """Applies human decisions on top of the parent run in a new revision; never calls the resolver."""
    started_at = now()
    bundle = read_inputs(input_path)
    result = close_month(bundle,closing_policy,period)
    decisions = validate_decisions(decisions,result)
    audit = AuditLog()
    revision = run_revision(bundle,result,closing_policy,inference_policy,parent_dir,decisions,audit)
    manifest = publish_result(bundle,result,closing_policy,period,output,revision=revision,started_at=started_at,layer={'ligada':False,'auditoria':True})
    audit.write(Path(output)/'auditoria.jsonl')
    return {'result':result, 'manifest':manifest, 'revision':revision, 'audit':audit}


def lines_read(bundle):
    """Rows read from each source file (and sheet), for the execution record in manifest.json."""
    counts = {}
    for rows in (bundle.checkout, bundle.contracts, bundle.remittances, bundle.bank_entries):
        for row in rows:
            name, sheet = row['_source']['arquivo_origem'], row['_source']['aba_origem']
            entry = counts.setdefault(name,{'linhas_lidas':0})
            entry['linhas_lidas'] += 1
            if sheet:
                entry.setdefault('linhas_por_aba',{})
                entry['linhas_por_aba'][sheet] = entry['linhas_por_aba'].get(sheet,0)+1
    for name, meta in bundle.sources.items():
        if meta.get('kind') == 'accounts' and meta.get('status') != 'BLOQUEADO':
            counts[name] = {'linhas_lidas':len(bundle.accounts)}
        elif meta.get('status') == 'BLOQUEADO':
            counts[name] = {'linhas_lidas':0}
    return counts


def now():
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


def same_manifest(saved,current):
    """A rerun into the same folder confirms it when everything but the execution timestamps is identical."""
    try:
        saved = json.loads(saved)
    except ValueError:
        return False
    for manifest in (saved,current):
        manifest.get('execucao',{}).pop('iniciada_em',None)
        manifest.get('execucao',{}).pop('concluida_em',None)
    return encode_json(saved) == encode_json(current)


def publish_result(bundle,result,policy,period,output,revision=None,started_at=None,layer=None):
    started_at = started_at or now()
    output = Path(output).resolve()
    engine_digest = hashlib.sha256()
    for path in sorted(Path(__file__).parent.glob('*.py')):
        engine_digest.update(path.name.encode())
        engine_digest.update(path.read_bytes())
    source_hashes = {key:value['sha256'] for key,value in bundle.sources.items()}
    identity = {'period':period,'sources':source_hashes,'policy':policy,'engine':engine_digest.hexdigest()}
    if revision:
        identity['revision'] = revision
    fingerprint = hashlib.sha256(encode_json(identity).encode()).hexdigest()
    run_id = f'{period}-rev{revision["numero"]}-{fingerprint[:16]}' if revision else f'{period}-{fingerprint[:16]}'
    contents = {name+'.csv':encode_csv(name,rows).encode('utf-8') for name,rows in {**result.tables,'rastro':result.traces,'cobertura':result.coverage}.items()}
    contents['checks.json'] = encode_json(result.checks).encode()
    contents['policy.json'] = encode_json(policy).encode()
    contents['metrics.json'] = encode_json(result.metrics).encode()
    contents['index.html'] = render_report(result,bundle,policy,run_id,output).encode('utf-8')
    for counterpart, items in result.contests.items():
        slug = counterpart.lower()
        contents[f'contestacoes/operacoes_{slug}.csv'] = encode_rows(items).encode('utf-8')
        contents[f'contestacoes/rascunho_{slug}.txt'] = contest_draft(counterpart,items,period).encode('utf-8')
    for name,content in bundle.attachments.items():
        contents['anexos/'+name] = content
    counts = lines_read(bundle)
    manifest = {'run_id':run_id,'period':period,'status':result.metrics['status'],'engine_version':__version__,'engine_sha256':engine_digest.hexdigest(),'sources':{name:{**{k:v for k,v in meta.items() if k != 'path'},**counts.get(name,{})} for name,meta in bundle.sources.items()},'output_sha256':{key:hashlib.sha256(content).hexdigest() for key,content in contents.items()},'rules':policy['status'],'slack_read':True}
    manifest['camada'] = {'ligada':bool((layer or {}).get('ligada')), 'auditoria':bool((layer or {}).get('auditoria'))}
    if revision:
        manifest['revisao'] = revision
    manifest['execucao'] = {'iniciada_em':started_at,'concluida_em':now(),'fuso':'UTC',
                            'linhas_lidas_total':sum(entry['linhas_lidas'] for entry in counts.values())}
    contents['manifest.json'] = encode_json(manifest).encode()
    if output.exists():
        for name,content in contents.items():
            destination = output/name
            if name == 'manifest.json':
                if not destination.is_file() or not same_manifest(destination.read_text(encoding='utf-8'),json.loads(content)):
                    raise ValueError('Output directory differs from this execution; choose a new --output directory. No files were overwritten.')
                continue
            if not destination.is_file() or destination.read_bytes() != content:
                raise ValueError('Output directory differs from this execution; choose a new --output directory. No files were overwritten.')
        # Confirmed, nothing written: the manifest that describes the folder is the saved one, with its own timestamps.
        return json.loads((output/'manifest.json').read_text(encoding='utf-8'))
    output.parent.mkdir(parents=True,exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix='.closing-stage-',dir=output.parent)).resolve()
    if staging.parent != output.parent or staging == output:
        raise ValueError('Invalid staging path')
    for name,content in contents.items():
        target = staging/name
        if not target.resolve().is_relative_to(staging):
            raise ValueError('Artifact path escapes staging directory')
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(content)
    for name,expected in manifest['output_sha256'].items():
        if hashlib.sha256((staging/name).read_bytes()).hexdigest() != expected:
            raise ValueError('Saved artifact checksum mismatch')
    staging.rename(output)
    return manifest
"""Job worker: runs closings and revisions with the same runner functions the CLI uses (ADR 0002, Fase 4)."""
from pathlib import Path
import csv
import json
import logging
import shutil
import tempfile
import threading
import time

from psycopg.types.json import Jsonb

from api import jobs, storage
from api.cache import PostgresResponseCache
from api.db import connect, migrate
from api.settings import Settings
from tarvo_close import runner
from tarvo_close.inference_policy import effective_mode, load_inference_policy
from tarvo_close.resolver import TokenBudget

log = logging.getLogger('api')
USER_ERRORS = (ValueError, KeyError, TypeError, OSError, ImportError)


def lineage_root(conn, fechamento_id):
    """The original closing of a lineage (revisions have no upload of their own)."""
    current = fechamento_id
    while True:
        row = conn.execute('SELECT pai_id FROM fechamentos WHERE id=%s',(current,)).fetchone()
        if row is None or row['pai_id'] is None:
            return current
        current = row['pai_id']


def input_path(settings, cliente_id, root_id):
    folder = storage.input_dir(settings,cliente_id,root_id)
    zips = sorted(folder.glob('*.zip'))
    return zips[0] if len(zips) == 1 else folder


def result_dir(settings, cliente_id, root_id, numero):
    return storage.output_dir(settings,cliente_id,root_id) if not numero else storage.revision_dir(settings,cliente_id,root_id,numero)


def _policy(conn, policy_id):
    return conn.execute('SELECT conteudo FROM politicas WHERE id=%s',(policy_id,)).fetchone()['conteudo']


def _validated_inference(content):
    with tempfile.TemporaryDirectory(prefix='inference-policy-') as folder:  # reuse the file validator the CLI uses
        path = Path(folder)/'inference-policy.json'
        path.write_text(json.dumps(content),encoding='utf-8')
        return load_inference_policy(path)


def _read_jsonl(path):
    if not path.is_file():
        return []
    return [json.loads(line) for line in path.read_text(encoding='utf-8').splitlines() if line.strip()]


def _store(conn, fech, out, done, revision, inference):
    metrics = json.loads((out/'metrics.json').read_text(encoding='utf-8'))
    checks = json.loads((out/'checks.json').read_text(encoding='utf-8'))
    status = 'PROVISORIO' if metrics.get('status') == 'PROVISORIO' else 'CONCLUIDO'
    conn.execute('UPDATE fechamentos SET status=%s, run_id=%s, metrics=%s, checks=%s, erro=NULL, concluido_em=now() WHERE id=%s',
                 (status,done['manifest']['run_id'],Jsonb(metrics),Jsonb(checks),fech['id']))
    events = _read_jsonl(out/'auditoria.jsonl')
    conn.execute('DELETE FROM auditoria WHERE fechamento_id=%s',(fech['id'],))
    conn.execute('DELETE FROM excecoes WHERE fechamento_id=%s',(fech['id'],))
    for seq, event in enumerate(events):
        conn.execute('INSERT INTO auditoria (fechamento_id, seq, evento) VALUES (%s,%s,%s)',(fech['id'],seq,Jsonb(event)))
    with open(out/'pendencias.csv',encoding='utf-8',newline='') as handle:
        pending = {row['id_saida']:row['status'] for row in csv.DictReader(handle,delimiter=';')}
    decided = {e['excecao_id'] for e in events if e.get('evento') == 'DECISAO_APLICADA' and e.get('resultado') == 'APLICADA'}
    # the queue always exists: one row per exception of the closing, with or without the inference layer
    rows = {}
    for exc in done['result'].exceptions:
        item = exc.as_dict()
        rows[item['excecao_id']] = {'classe':item['classe'], 'tipo':item['tipo'], 'modo':effective_mode(inference,item['classe']), 'resultado':'SEM_CAMADA', 'motivo':None,
                                    'proposta':None, 'verificacoes':[], 'aplicada':False, 'escopo':item['escopo'],
                                    'valor_brl':None if item['valor_brl'] is None else str(item['valor_brl']),
                                    'motivo_pendencia':item['motivo'], 'quem_decide':item['quem_decide']}
    for event in events:
        # an original run stores its own events; a revision stores the inherited ones too, so its rows carry the new pendencia_status
        if event.get('evento') != 'EXCECAO' or (event.get('herdado') and not revision):
            continue
        row = rows.setdefault(event['excecao_id'],{'classe':event['classe'], 'tipo':event['tipo'], 'modo':event['modo'], 'escopo':None, 'valor_brl':None,
                                                   'motivo_pendencia':None, 'quem_decide':None})
        row.update(resultado=event['resultado'], motivo=event.get('motivo'), proposta=event.get('proposta'), verificacoes=event.get('verificacoes') or [],
                   aplicada=bool(event.get('aplicada')))
    for excecao_id, row in rows.items():
        conn.execute('INSERT INTO excecoes (fechamento_id, excecao_id, classe, tipo, modo, resultado, motivo, proposta, verificacoes, aplicada, pendencia_status, escopo, valor_brl, motivo_pendencia, quem_decide) '
                     'VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)',
                     (fech['id'],excecao_id,row['classe'],row['tipo'],row['modo'],row['resultado'],row['motivo'],
                      Jsonb(row['proposta']) if row['proposta'] is not None else None,Jsonb(row['verificacoes']),
                      row['aplicada'] or excecao_id in decided,pending.get(excecao_id),row['escopo'],row['valor_brl'],row['motivo_pendencia'],row['quem_decide']))
    return status


def process(job, conn, settings, resolver=None):
    started = time.monotonic()
    fech = conn.execute('SELECT * FROM fechamentos WHERE id=%s',(job['fechamento_id'],)).fetchone()
    conn.execute("UPDATE fechamentos SET status='PROCESSANDO' WHERE id=%s",(fech['id'],))
    conn.commit()
    status = 'ERRO'
    try:
        closing = _policy(conn,fech['politica_closing_id'])
        inference = _validated_inference(_policy(conn,fech['politica_inference_id']))
        cliente, root = fech['cliente_id'], lineage_root(conn,fech['id'])
        source = input_path(settings,cliente,root)
        out = result_dir(settings,cliente,root,fech['numero_revisao'])
        shutil.rmtree(out,ignore_errors=True)
        warning = None
        if job['tipo'] == 'REVISAO':
            payload = job['payload']
            parent = conn.execute('SELECT numero_revisao FROM fechamentos WHERE id=%s',(payload['pai_id'],)).fetchone()
            done = runner.run_revision_closing(source,closing,inference,fech['periodo'],out,result_dir(settings,cliente,root,parent['numero_revisao']),payload['decisoes'])
        else:
            done = runner.run_closing(source,closing,inference,fech['periodo'],out,resolver=resolver,cache=PostgresResponseCache(lambda: connect(settings.database_url),cliente),
                                      budget=TokenBudget(settings.llm_budget_tokens),use_llm=fech['usar_llm'])
            warning = done['aviso']
        status = _store(conn,fech,out,done,job['tipo'] == 'REVISAO',inference)
        conn.execute('UPDATE fechamentos SET aviso=%s WHERE id=%s',(warning,fech['id']))
        jobs.finish(conn,job['id'])
    except Exception as error:  # the job must always end in a final state; the message never carries a traceback
        conn.rollback()
        message = f'{type(error).__name__}: {error}'[:500] if isinstance(error,USER_ERRORS) and not isinstance(error,OSError) else f'Erro interno ao processar ({type(error).__name__})'
        conn.execute("UPDATE fechamentos SET status='ERRO', erro=%s, concluido_em=now() WHERE id=%s",(message,fech['id']))
        jobs.fail(conn,job['id'],message)
    log.info('job id=%s fechamento=%s tipo=%s status=%s duracao_s=%.2f',job['id'],fech['id'],job['tipo'],status,time.monotonic()-started)
    return status


def run_once(conn_factory, settings, resolver=None):
    """Process one queued job. False when the queue is empty."""
    with conn_factory() as conn:
        job = jobs.claim(conn)
        conn.commit()
        if job is None:
            return False
        process(job,conn,settings,resolver)
    return True


def run_forever(conn_factory, settings, interval=1.0, stop=None, resolver=None):
    stop = stop or threading.Event()
    while not stop.is_set():
        try:
            worked = run_once(conn_factory,settings,resolver)
        except Exception as error:  # database down: keep the loop alive
            log.error('worker erro=%s',type(error).__name__)
            worked = False
        if not worked:
            stop.wait(interval)


def main():
    logging.basicConfig(level=logging.INFO)
    settings = Settings.from_env()
    with connect(settings.database_url) as conn:
        migrate(conn)
    run_forever(lambda: connect(settings.database_url),settings)


if __name__ == '__main__':
    main()

"}

