.timeline::before{content:"";position:absolute;left:0;right:0;top:9px;height:1px;background:linear-gradient(90deg,var(--ember),var(--green));transform-origin:left;transform:scaleX(var(--tl,0));transition:transform 1.6s var(--ease)}
.timeline.in{--tl:1}
.timeline li{position:relative;padding-top:34px}
